def find_fewest_coins(coins, target):
    """
    Return a list of coins (values from `coins`) that sum to `target` using the
    fewest number of coins possible. If it's impossible to make the target,
    raise ValueError with a descriptive message.

    coins: iterable of positive integers (coin denominations)
    target: non-negative integer (amount to make)
    """
    if target < 0:
        raise ValueError("target can't be negative")
    if target == 0:
        return []

    # Keep only positive integer coin denominations
    coins = [c for c in coins if isinstance(c, int) and c > 0]
    if not coins:
        raise ValueError("can't make target with given coins")

    # dp[i] will hold a list of coins that sum to i with minimal length, or None
    dp = [None] * (target + 1)
    dp[0] = []

    for amount in range(1, target + 1):
        best = None
        for coin in coins:
            if coin <= amount and dp[amount - coin] is not None:
                candidate = dp[amount - coin] + [coin]
                if best is None or len(candidate) < len(best):
                    best = candidate
        dp[amount] = best

    if dp[target] is None:
        raise ValueError("can't make target with given coins")

    # Return in ascending order for consistency
    return sorted(dp[target])
